-- civgraph records database: phase 2 tables (generated by scripts/records/schema.mjs --sql).

-- Created beside the live tables (elections, constituencies, candidates, counts,

-- constituency_animation, constituency_features, browse_*), which this migration does not touch.

-- dataset already exists in production (the elections loader made it): IF NOT EXISTS.



CREATE TABLE IF NOT EXISTS dataset (
  key TEXT NOT NULL,
  value TEXT,
  PRIMARY KEY (key)
);

CREATE TABLE documents (
  name TEXT NOT NULL,
  body TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (name)
);

CREATE TABLE r_elections (
  key TEXT NOT NULL,
  slug TEXT NOT NULL,
  body_slug TEXT NOT NULL,
  body TEXT,
  body_group TEXT,
  display_title TEXT,
  contest_type TEXT,
  kind TEXT,
  voting_system TEXT,
  contest_status TEXT,
  date TEXT NOT NULL,
  year INTEGER,
  decade INTEGER,
  source_map_id TEXT,
  layer_id TEXT,
  label_property TEXT,
  candidate_rows_expected INTEGER,
  transfer_data_expected INTEGER,
  previous_key TEXT,
  placeholder INTEGER,
  ord INTEGER NOT NULL,
  compact INTEGER,
  meta TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (key)
);
CREATE UNIQUE INDEX r_elections_slug ON r_elections(slug);
CREATE INDEX r_elections_body_date ON r_elections(body_slug, date, key);
CREATE INDEX r_elections_date ON r_elections(date, key);

CREATE TABLE election_aggregates (
  election_key TEXT NOT NULL,
  name TEXT NOT NULL,
  part INTEGER NOT NULL,
  payload TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key, name, part)
);

CREATE TABLE contests (
  election_key TEXT NOT NULL,
  seq INTEGER NOT NULL,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  source_file TEXT,
  seats_total INTEGER,
  electorate INTEGER,
  quota REAL,
  turnout_pct REAL,
  winner_party TEXT,
  winner_name TEXT,
  leading_party TEXT,
  leading_name TEXT,
  leading_votes REAL,
  leading_pct REAL,
  majority REAL,
  majority_pct REAL,
  seats_won INTEGER,
  meta TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key, seq)
);
CREATE INDEX contests_slug ON contests(election_key, slug, seq);
CREATE INDEX contests_source_file ON contests(source_file);

CREATE TABLE candidacies (
  election_key TEXT NOT NULL,
  contest_seq INTEGER NOT NULL,
  ord INTEGER NOT NULL,
  candidate_id TEXT,
  person_id TEXT,
  name TEXT,
  name_as_printed TEXT,
  party_as_printed TEXT,
  party_label TEXT,
  party_rule INTEGER,
  party_id TEXT,
  ballot_description TEXT,
  first_prefs REAL,
  final_votes REAL,
  elected INTEGER,
  elected_at INTEGER,
  excluded INTEGER,
  excluded_at INTEGER,
  status TEXT,
  unopposed INTEGER,
  colour TEXT,
  gender TEXT,
  meta TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key, contest_seq, ord)
);
CREATE INDEX cand_person ON candidacies(person_id, election_key, contest_seq, ord);
CREATE INDEX cand_party ON candidacies(party_id, election_key);
CREATE INDEX cand_label ON candidacies(party_label);

CREATE TABLE r_counts (
  election_key TEXT NOT NULL,
  contest_seq INTEGER NOT NULL,
  ord INTEGER NOT NULL,
  row_id INTEGER,
  candidacy_ord INTEGER,
  candidate_id TEXT,
  count_number INTEGER,
  total_votes REAL,
  transfers REAL,
  status TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key, contest_seq, ord)
);

CREATE TABLE contest_animation (
  election_key TEXT NOT NULL,
  contest_seq INTEGER NOT NULL,
  payload TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key, contest_seq)
);

CREATE TABLE contest_features (
  election_key TEXT NOT NULL,
  contest_seq INTEGER NOT NULL,
  layer_id TEXT,
  feature_id TEXT,
  feature_name TEXT,
  match_name TEXT,
  matched INTEGER,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key, contest_seq)
);
CREATE INDEX confeat_layer ON contest_features(layer_id, feature_id);

CREATE TABLE election_summaries (
  election_key TEXT NOT NULL,
  file TEXT NOT NULL,
  summary TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key)
);
CREATE UNIQUE INDEX election_summaries_file ON election_summaries(file);

CREATE TABLE election_manifest (
  key TEXT NOT NULL,
  ord INTEGER NOT NULL,
  entry TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (key)
);
CREATE INDEX election_manifest_ord ON election_manifest(ord, key);

CREATE TABLE election_cards (
  slug TEXT NOT NULL,
  id TEXT,
  key TEXT,
  entry_kind TEXT,
  election_key TEXT,
  title TEXT,
  title_norm TEXT,
  search_norm TEXT,
  body_slug TEXT,
  body TEXT,
  date TEXT,
  decade TEXT,
  kind TEXT,
  ord INTEGER NOT NULL,
  card TEXT NOT NULL,
  list_card TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX election_cards_ord ON election_cards(ord, slug);
CREATE INDEX election_cards_election ON election_cards(election_key, ord);
CREATE INDEX election_cards_body ON election_cards(body_slug, ord);
CREATE INDEX election_cards_key ON election_cards(key);

CREATE TABLE election_details (
  slug TEXT NOT NULL,
  election_key TEXT,
  detail TEXT,
  contests TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX election_details_key ON election_details(election_key);

CREATE TABLE persons (
  person_id TEXT NOT NULL,
  registry_id TEXT,
  display_name TEXT NOT NULL,
  first_year INTEGER,
  last_year INTEGER,
  provisional INTEGER,
  candidacies INTEGER,
  ord INTEGER NOT NULL,
  meta TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (person_id)
);

CREATE TABLE person_names (
  name_id TEXT NOT NULL,
  person_id TEXT NOT NULL,
  name TEXT,
  candidacies INTEGER,
  first_year INTEGER,
  last_year INTEGER,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (name_id, person_id)
);
CREATE INDEX person_names_person ON person_names(person_id, name_id);

CREATE TABLE person_aliases (
  alias TEXT NOT NULL,
  slug TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (alias)
);

CREATE TABLE person_merges (
  drop_id TEXT NOT NULL,
  keep_id TEXT NOT NULL,
  confirmed INTEGER,
  meta TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (drop_id)
);

CREATE TABLE person_facts (
  person_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  ord INTEGER NOT NULL,
  value TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (person_id, kind, ord)
);

CREATE TABLE person_cards (
  slug TEXT NOT NULL,
  id TEXT,
  title TEXT,
  title_norm TEXT,
  key_norm TEXT,
  search_norm TEXT,
  first_year INTEGER,
  last_year INTEGER,
  bodies TEXT,
  decades TEXT,
  elected TEXT,
  contests INTEGER,
  elected_count INTEGER,
  ord INTEGER NOT NULL,
  card TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX person_cards_ord ON person_cards(ord);
CREATE INDEX person_cards_title ON person_cards(title_norm);
CREATE INDEX person_cards_key ON person_cards(key_norm);
CREATE INDEX person_cards_id ON person_cards(id);
CREATE INDEX person_cards_first_year ON person_cards(first_year);
CREATE INDEX person_cards_last_year ON person_cards(last_year);
CREATE INDEX person_cards_contests ON person_cards(contests);
CREATE INDEX person_cards_elected_count ON person_cards(elected_count);

CREATE TABLE person_cards_facets (
  id INTEGER NOT NULL,
  facets TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE parties (
  party_id TEXT NOT NULL,
  type TEXT,
  name TEXT,
  short_name TEXT,
  founded TEXT,
  founded_precision TEXT,
  dissolved TEXT,
  status TEXT,
  provisional INTEGER,
  confidence TEXT,
  ord INTEGER NOT NULL,
  meta TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (party_id)
);

CREATE TABLE party_names (
  party_id TEXT NOT NULL,
  ord INTEGER NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL,
  valid_from TEXT,
  valid_until TEXT,
  bodies TEXT,
  meta TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (party_id, ord)
);
CREATE INDEX party_names_name ON party_names(name, party_id);

CREATE TABLE party_events (
  ord INTEGER NOT NULL,
  party_id TEXT NOT NULL,
  date TEXT,
  kind TEXT,
  related TEXT,
  meta TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (ord)
);
CREATE INDEX party_events_party ON party_events(party_id, date, ord);

CREATE TABLE party_label_map (
  label TEXT NOT NULL,
  party_slug TEXT NOT NULL,
  ord INTEGER NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (label)
);

CREATE TABLE party_aliases (
  alias TEXT NOT NULL,
  slug TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (alias)
);

CREATE TABLE party_cards (
  slug TEXT NOT NULL,
  id TEXT,
  title TEXT,
  title_norm TEXT,
  search_norm TEXT,
  occurrences INTEGER,
  ord INTEGER NOT NULL,
  card TEXT NOT NULL,
  detail TEXT,
  profile TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX party_cards_ord ON party_cards(ord);

CREATE TABLE sources (
  slug TEXT NOT NULL,
  id TEXT,
  title TEXT,
  title_norm TEXT,
  key_norm TEXT,
  search_norm TEXT,
  provider TEXT,
  category TEXT,
  publication_status TEXT,
  date TEXT,
  license TEXT,
  ord INTEGER NOT NULL,
  card TEXT NOT NULL,
  detail TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX sources_ord ON sources(ord);
CREATE INDEX sources_title ON sources(title_norm);
CREATE INDEX sources_key ON sources(key_norm);
CREATE INDEX sources_id ON sources(id);
CREATE INDEX sources_provider ON sources(provider);
CREATE INDEX sources_category ON sources(category);
CREATE INDEX sources_publication_status ON sources(publication_status);
CREATE INDEX sources_date ON sources(date);
CREATE INDEX sources_license ON sources(license);

CREATE TABLE sources_facets (
  id INTEGER NOT NULL,
  facets TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE source_aliases (
  alias TEXT NOT NULL,
  slug TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (alias)
);

CREATE TABLE source_merges (
  ord INTEGER NOT NULL,
  item TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (ord)
);

CREATE TABLE contest_provenance (
  source_file TEXT NOT NULL,
  election_key TEXT,
  contest_seq INTEGER,
  body TEXT,
  date TEXT,
  constituency TEXT,
  status TEXT,
  ord INTEGER NOT NULL,
  record TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (source_file)
);
CREATE INDEX contest_provenance_contest ON contest_provenance(election_key, contest_seq);
CREATE INDEX contest_provenance_ord ON contest_provenance(ord);

CREATE TABLE citations (
  subject_type TEXT NOT NULL,
  subject_key TEXT NOT NULL,
  ord INTEGER NOT NULL,
  title TEXT,
  publisher TEXT,
  url TEXT,
  archive_url TEXT,
  host TEXT,
  kind TEXT,
  origin TEXT,
  basis TEXT,
  scope TEXT,
  checked INTEGER,
  match TEXT,
  document TEXT,
  citation TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (subject_type, subject_key, ord)
);
CREATE INDEX citations_url ON citations(url);

CREATE TABLE legislation (
  legislation_id TEXT NOT NULL,
  title TEXT,
  url TEXT,
  ord INTEGER NOT NULL,
  meta TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (legislation_id)
);

CREATE TABLE election_legislation (
  source_file TEXT NOT NULL,
  ord INTEGER NOT NULL,
  legislation_id TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (source_file, ord)
);
CREATE INDEX election_legislation_id ON election_legislation(legislation_id);

CREATE TABLE provenance_shards (
  election_key TEXT NOT NULL,
  shard TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (election_key)
);

CREATE TABLE register_entries (
  slug TEXT NOT NULL,
  id TEXT,
  title TEXT,
  title_norm TEXT,
  key_norm TEXT,
  search_norm TEXT,
  member_name TEXT,
  elected_body TEXT,
  category TEXT,
  date TEXT,
  constituency TEXT,
  member_type TEXT,
  chamber TEXT,
  interest_count INTEGER,
  source_count INTEGER,
  nil_status TEXT,
  ord INTEGER NOT NULL,
  card TEXT NOT NULL,
  detail TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX register_entries_ord ON register_entries(ord);
CREATE INDEX register_entries_title ON register_entries(title_norm);
CREATE INDEX register_entries_key ON register_entries(key_norm);
CREATE INDEX register_entries_id ON register_entries(id);
CREATE INDEX register_entries_member_name ON register_entries(member_name);
CREATE INDEX register_entries_elected_body ON register_entries(elected_body);
CREATE INDEX register_entries_date ON register_entries(date);
CREATE INDEX register_entries_constituency ON register_entries(constituency);
CREATE INDEX register_entries_member_type ON register_entries(member_type);
CREATE INDEX register_entries_chamber ON register_entries(chamber);
CREATE INDEX register_entries_interest_count ON register_entries(interest_count);
CREATE INDEX register_entries_source_count ON register_entries(source_count);
CREATE INDEX register_entries_nil_status ON register_entries(nil_status);

CREATE TABLE register_entries_facets (
  id INTEGER NOT NULL,
  facets TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE register_entries_aliases (
  alias TEXT NOT NULL,
  slug TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (alias)
);

CREATE TABLE divisions (
  division_id TEXT NOT NULL,
  shard INTEGER NOT NULL,
  ord INTEGER NOT NULL,
  body TEXT,
  date TEXT,
  number TEXT,
  title TEXT,
  record TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (division_id)
);
CREATE INDEX divisions_shard ON divisions(shard, ord);
CREATE INDEX divisions_body_date ON divisions(body, date, division_id);

CREATE TABLE division_votes (
  division_id TEXT NOT NULL,
  ord INTEGER NOT NULL,
  person_id TEXT,
  vote TEXT,
  party TEXT,
  entry TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (division_id, ord)
);
CREATE INDEX dvotes_person ON division_votes(person_id, division_id);

CREATE TABLE vote_persons (
  person_id TEXT NOT NULL,
  record TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (person_id)
);

CREATE TABLE vote_parties (
  slug TEXT NOT NULL,
  record TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);

CREATE TABLE graph_entities (
  entity_id TEXT NOT NULL,
  shard INTEGER NOT NULL,
  ord INTEGER NOT NULL,
  slug TEXT,
  label TEXT,
  label_norm TEXT,
  entity TEXT NOT NULL,
  summary TEXT,
  search TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (entity_id)
);
CREATE INDEX graph_entities_shard ON graph_entities(shard, ord);
CREATE INDEX graph_entities_slug ON graph_entities(slug);
CREATE INDEX graph_entities_label ON graph_entities(label_norm);

CREATE TABLE graph_browse_keys (
  browse_key TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (browse_key)
);

CREATE TABLE graph_statements (
  subject_id TEXT NOT NULL,
  ord INTEGER NOT NULL,
  statement_id TEXT,
  property_id TEXT,
  statement TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (subject_id, ord)
);

CREATE TABLE graph_reverse (
  entity_id TEXT NOT NULL,
  ord INTEGER NOT NULL,
  item TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (entity_id, ord)
);

CREATE TABLE graph_source_statements (
  source_id TEXT NOT NULL,
  ord INTEGER NOT NULL,
  item TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (source_id, ord)
);

